5550	func brainBriefRawHistoryQueries(task string) []string {
5551		seen := map[string]struct{}{}
5552		var queries []string
5553		for _, identifier := range historyIdentifierQueryTerms(task) {
5554			normalized := strings.ToLower(strings.Trim(identifier, "_"))
5555			if normalized == "" || normalized == "ultron" || normalized == "api" || normalized == "apis" {
5556				continue
5557			}
5558			// Raw scanning is a precision fallback for code-shaped identifiers. Short
5559			// all-caps acronyms such as MCP, HTTP, CLI, or JSON occur throughout tool
5560			// manifests and captured environment context; using them alone returns the
5561			// first noisy transcript lines and displaces indexed history ranking.
5562			if identifier == strings.ToUpper(identifier) &&
5563				len([]rune(identifier)) <= 4 &&
5564				!strings.Contains(identifier, "_") &&
5565				!strings.ContainsFunc(identifier, unicode.IsDigit) {
5566				continue
5567			}
5568			if _, ok := seen[identifier]; ok {
5569				continue
5570			}
5571			seen[identifier] = struct{}{}
5572			queries = append(queries, identifier)
5573		}
5574		sort.SliceStable(queries, func(i, j int) bool {
5575			left := brainBriefRawHistoryQueryPriority(queries[i])
5576			right := brainBriefRawHistoryQueryPriority(queries[j])
5577			if left != right {
5578				return left > right
5579			}
5580			return len(queries[i]) > len(queries[j])
5581		})
5582		if len(queries) > 8 {
5583			queries = queries[:8]
5584		}
5585		return queries
5586	}
