// regressionScanHistoryCapped walks the raw brain (sessions + exports) once and extracts
// change/delete signals for the given identifiers from every matching line of every file it
// reaches, so rare but precise invariants are not lost behind a top-N ranking.
//
// It is NOT unbounded, and the bound is not cosmetic: the walk stops outright (filepath.SkipAll)
// once it has opened maxFiles history files, or once it holds maxSignalsEach distinct change
// signals AND maxSignalsEach distinct delete signals. Whatever lies beyond that point in the walk
// is never read. The returned regressionScanCaps says whether that happened; callers must surface
// it, because "no signal found" and "stopped looking" are different answers.
func regressionScanHistoryCapped(brainDir string, ids []string) ([]changeSignal, []deleteSignal, map[string]struct{}, regressionScanCaps, error) {
	const (
		maxFiles       = 20000
		maxLineBytes   = 4 * 1024 * 1024
		maxSignalsEach = 400
	)
	caps := regressionScanCaps{MaxFiles: maxFiles, MaxSignals: maxSignalsEach}
	lowIDs := make([]string, 0, len(ids))
	for _, id := range ids {
		lowIDs = append(lowIDs, strings.ToLower(id))
	}
	catalog, catalogErr := catalogTranscriptRels(brainDir)
	if catalogErr != nil {
		return nil, nil, nil, caps, catalogErr
	}
	var changes []changeSignal
	var deletes []deleteSignal
	files := map[string]struct{}{}
	seenC := map[string]int{}
	seenD := map[string]int{}
	scanned := 0
	_ = filepath.WalkDir(brainDir, func(path string, d fs.DirEntry, err error) error {
			lineNo++
			line := sc.Text()
			low := strings.ToLower(line)
			matched := false
			for _, id := range lowIDs {
				if !strings.Contains(low, id) {
					continue
				}
				matched = true
				ex := normalizeHistoryTextForExcerpt(line)
				ev := relSlash + ":" + strconv.Itoa(lineNo)
				c, dl := regressionExtractSignals(id, ex, ev)
				hints := regressionLineFileHints(line)
				for _, s := range c {
					s.hints = hints
					k := s.id + "|" + s.operand
					if idx, ok := seenC[k]; ok {
						changes[idx].hints = mergeRegressionHints(changes[idx].hints, hints)
					} else {
						seenC[k] = len(changes)
						changes = append(changes, s)
					}
				}
				for _, s := range dl {
					s.hints = hints
					k := s.target + "|" + s.rhs
					if idx, ok := seenD[k]; ok {
						deletes[idx].hints = mergeRegressionHints(deletes[idx].hints, hints)
						deletes[idx].anchors = mergeRegressionHints(deletes[idx].anchors, s.anchors)
					} else {
						seenD[k] = len(deletes)
						deletes = append(deletes, s)
					}
				}
			}
			if matched {
				for _, fn := range regressionLineFileHints(line) {
					files[fn] = struct{}{}
				}
			}
		}
		_ = f.Close()
		return nil
	})
	caps.Scanned = scanned
	return changes, deletes, files, caps, nil
}

