func brainBriefActionChecklist(repoRoot string, report brainBriefReport, task string) []brainBriefAction {
	families := brainBriefActionFamiliesForReport(report, task)
	var actions []brainBriefAction
	if families&brainBriefActionFamilyLimit != 0 {
		actions = append(actions, brainBriefLimitNormalizationActions(repoRoot, report.LikelyEditFiles)...)
	}
	if families&brainBriefActionFamilyMetadata != 0 {
		actions = append(actions, brainBriefMetadataStringActions(repoRoot, report.LikelyEditFiles)...)
	}
	if families&brainBriefActionFamilyPreviousResponse != 0 {
		return false
	}

	taskTerms := brainBriefFileMatchTerms(task)
	if len(taskTerms) < 2 {
		return false
	}
	excerptTerms := brainBriefFileMatchTerms(excerpt)
	if len(excerptTerms) == 0 {
		return false
	}
	present := make(map[string]struct{}, len(excerptTerms))
	for _, term := range excerptTerms {
		present[term] = struct{}{}
	}
	required := 2
	if len(taskTerms) >= 5 {
		required = 3
	}
	hits := 0
	domainHit := false
	for _, term := range taskTerms {
		if _, ok := present[term]; !ok {
			continue
		}
		hits++
		if _, generic := brainBriefActionGenericOverlapTerms[term]; !generic {
			domainHit = true
		}
	}
	return hits >= required && domainHit
}

func brainBriefActionStrongIdentifiers(task string) []string {
	queries := taskIdentifierQueries(task)
	identifiers := queries[:0]
	for _, identifier := range queries {
		// Short all-caps words such as SQL/CLI are identifier-like to the history
		// tokenizer but are not strong enough to bind an action invariant to one
		// task. Real symbol/constant anchors remain well above this floor.
		if utf8.RuneCountInString(strings.Trim(identifier, "_")) >= 6 {
			identifiers = append(identifiers, identifier)
		}
	}
	return identifiers
}

