func compareGuideText(brain, graph []byte, requireParity bool) error {
	if bytes.Equal(brain, graph) {
		return nil
	}
	if requireParity {
		return fmt.Errorf("Brain and Graph must render identical guide text")
	}
	legacy := strings.NewReplacer(
